 if(fc&&!cards.appr){const h4=[...fc.querySelectorAll('h4')].find(x=>/approval by/i.test(txt(x)));if(h4){const sc=h4.nextElementSibling,nc=document.createElement('div');nc.className='c';nc.innerHTML='<h3></h3>';if(sc)nc.appendChild(sc);h4.remove();fc.after(nc);cards.appr=nc;nc.querySelector('h3').textContent='Approval by a project manager'}}
 const have=TABS.filter(T=>cards[T.k]);if(!have.length)return;
 let cur=S.accTab;if(!have.some(T=>T.k==cur))cur=have[0].k;
 const bar=document.createElement('div');bar.id='accx';bar.className='c accx-hero';
 bar.innerHTML=`<div class="accx-top"><div>${sh('key','','#0b7285')}</div><div style="flex:1;min-width:220px"><h2>Access control</h2><p>Decide what each type of account can see and do. Pick a part below.</p></div></div><div class="accx-tabs" role="tablist">${have.map(T=>`<button type="button" role="tab" data-k="${T.k}" class="${T.k==cur?'on':''}" style="--tc:${T.c}"><span class="ti">${ic(T.icon)}</span><span class="tt"><b>${T.t}</b><small>${esc(T.card)}</small></span></button>`).join('')}</div>`;
