/* ---------- reading the answer ---------- */
function apMd(t){const L=String(t||'').split('\n'),o=[];
 for(let l of L){const x=esc(l).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\b([A-Z]{2,6}-\d{1,4})\b/g,(m,id)=>S.c&&S.c[id]?`<a onclick="go('item','${id}')">${id}</a>`:m);
  let m;if((m=/^\s*#+\s*(.*)$/.exec(x)))o.push(`<div class="ap-hd">${m[1]}</div>`);
  else if(/^\s*<b>[^<]+<\/b>:?\s*$/.test(x))o.push(`<div class="ap-hd">${x.trim()}</div>`);
  else if((m=/^\s*(\d{1,2})[.)]\s+(.*)$/.exec(x)))o.push(`<div class="ap-n"><b>${m[1]}</b><span>${m[2]}</span></div>`);
  else if((m=/^\s*[-*•]\s+(.*)$/.exec(x)))o.push(`<div class="aib">• ${m[1]}</div>`);
  else o.push(x.trim()?x+'<br>':'')}
 return o.join('').replace(/(<\/div>)<br>/g,'$1')}
const SECS=[['Summary','s1','Summary'],['Most likely causes','s2','Most likely causes'],['Checks to do','s3','Checks to do, in order'],['Fix','s4','Fix'],['If it is still not solved','s5','If it is still not solved'],['Prevent it next time','s6','Prevent it next time']];
function apSplit(t){const out={},ord=[];let cur=null;for(const line of String(t||'').split('\n')){const m=/^\s*(?:#+\s*)?\*\*([^*]+?)\*\*:?\s*(.*)$/.exec(line);let hit=null;if(m){const h=m[1].trim().toLowerCase();hit=SECS.find(s=>h.startsWith(s[0].toLowerCase()))}
  if(hit){cur=hit[2];if(!out[cur]){out[cur]='';ord.push(hit)}if(m[2].trim())out[cur]+=m[2].trim()+'\n'}else if(cur)out[cur]+=line+'\n'}
 return ord.length>=2?{o:out,ord}:null}
const apSecHtml=t=>{const p=apSplit(t);if(!p)return `<div class="ap-b" style="max-width:100%">${apMd(t)}</div>`;return p.ord.map(s=>`<div class="ap-sec ${s[1]}"><h5>${esc(s[2])}</h5><div class="bd">${apMd(p.o[s[2]].trim())}</div></div>`).join('')};

/* ---------- pictures ---------- */
function apShrink(file){return new Promise((ok,no)=>{if(!file||!/^image\//.test(file.type||''))return no(new Error('Only picture files can be added.'));const u=URL.createObjectURL(file),im=new Image();
 im.onload=()=>{try{const M=1280,k=Math.min(1,M/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*k));c.height=Math.max(1,Math.round(im.height*k));const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);g.drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(u);ok(c.toDataURL('image/jpeg',.82))}catch(e){no(e)}};
 im.onerror=()=>{URL.revokeObjectURL(u);no(new Error('That picture could not be read. Try a JPG or PNG.'))};im.src=u})}
async function apAdd(files,key){const list=key==='bs'?A().bs.imgs:A().imgs;let n=0;for(const f of [...(files||[])]){if(list.length>=4){say('Up to 4 pictures at a time.');break}try{list.push(await apShrink(f));n++}catch(e){say(e.message)}}if(n)apThumbs(key)}
function apThumbs(key){const el=document.getElementById(key==='bs'?'apBsTh':'apChTh');if(!el)return;const list=key==='bs'?A().bs.imgs:A().imgs;el.innerHTML=list.map((d,i)=>`<div class="im"><img src="${d}" alt=""><button title="Remove" onclick="apDel('${key}',${i})">×</button></div>`).join('');el.style.display=list.length?'flex':'none'}
function apDel(key,i){(key==='bs'?A().bs.imgs:A().imgs).splice(i,1);apThumbs(key)}
function apPick(key){const f=document.createElement('input');f.type='file';f.accept='image/*';f.multiple=true;f.onchange=()=>apAdd(f.files,key);f.click()}
const apPaste=(e,key)=>{const fs=[...(e.clipboardData&&e.clipboardData.files||[])].filter(f=>/^image\//.test(f.type));if(fs.length){e.preventDefault();apAdd(fs,key)}};
function apDrop(e,key){e.preventDefault();e.currentTarget.classList.remove('over');apAdd(e.dataTransfer.files,key)}

/* ---------- talking to the AI (answers appear as they are written) ---------- */
async function apStream(body,onT,ctl){const r=await fetch('/api/ai/chat',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify(Object.assign({stream:true},body)),signal:ctl.signal});
 if(!/ndjson/.test(r.headers.get('content-type')||'')){let j={};try{j=await r.json()}catch(e){}const er=new Error(j.error||('Error '+r.status));er.code=j.code;throw er}
 const rd=r.body.getReader(),dec=new TextDecoder();let buf='',full='';
 for(;;){const {done,value}=await rd.read();if(done)break;buf+=dec.decode(value,{stream:true});let i;while((i=buf.indexOf('\n'))>=0){const l=buf.slice(0,i);buf=buf.slice(i+1);if(!l.trim())continue;let j;try{j=JSON.parse(l)}catch(e){continue}if(j.err)throw new Error(j.err);if(j.t){full+=j.t;onT(full)}if(j.done)return j.text||full}}
 return full}
